SELECT p.gender, a.admittime, s.stay_id, i.itemid, i.value, i.valueuom, s.intime, s.outtime, s.los, c.charlson_comorbidity_cat, COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN p.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS mortality_rate, AVG(s.los) AS average_length_of_stay, COUNT(DISTINCT CASE WHEN i.itemid = 30874 THEN p.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS ckd_prevalence, COUNT(DISTINCT CASE WHEN i.itemid = 1507170 THEN p.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS diabetes_prevalence FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.stay_id = s.stay_id JOIN labevents i ON a.subject_id = i.subject_id AND a.hadm_id = i.hadm_id JOIN charlsoncomorbidity c ON c.charlson_comorbidity_cat BETWEEN 0 AND 2 AND c.charlson_comorbidity_cat IS NOT NULL WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 56 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2018 AND i.value IN ('Yes', '1') AND (s.los BETWEEN 1 AND 2 OR s.los BETWEEN 3 AND 5 OR s.los BETWEEN 6 AND 9 OR s.los >= 10) GROUP BY p.gender, a.admittime, s.stay_id, i.itemid, i.value, i.valueuom, s.intime, s.outtime, s.los, c.charlson_comorbidity_cat ORDER BY p.gender, a.admittime, s.stay_id, i.itemid, i.value, i.valueuom, s.intime, s.outtime, s.los, c.charlson_comorbidity_cat NULLS LAST;